//! Stable domain types shared by the control plane and worker.
//!
//! Durable task and attempt identities plus the lifecycle states that
//! the control plane persists outside disposable Kubernetes resources.

use serde::{Deserialize, Serialize};
use std::{collections::BTreeSet, fmt};
use thiserror::Error;
use uuid::Uuid;

/// Identifies the current domain-model revision.
#[must_use]
pub const fn model_revision() -> u8 {
    3
}

/// A durable task identity generated by the control plane.
#[derive(Clone, Copy, Debug, Deserialize, Eq, Hash, PartialEq, Serialize)]
#[serde(transparent)]
pub struct TaskId(Uuid);

impl TaskId {
    /// Generates a time-ordered durable task identity.
    #[must_use]
    pub fn generate() -> Self {
        Self(Uuid::now_v7())
    }

    /// Parses a task identity returned by the control plane.
    ///
    /// # Errors
    ///
    /// Returns [`LifecycleError`] when `value` is not a UUID.
    pub fn parse(value: &str) -> Result<Self, LifecycleError> {
        Uuid::parse_str(value)
            .map(Self)
            .map_err(|_| LifecycleError::InvalidTaskId(value.to_owned()))
    }
}

impl fmt::Display for TaskId {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.0.fmt(formatter)
    }
}

/// A durable execution identity belonging to exactly one task.
#[derive(Clone, Copy, Debug, Deserialize, Eq, Hash, PartialEq, Serialize)]
#[serde(transparent)]
pub struct AttemptId(Uuid);

impl AttemptId {
    /// Generates a time-ordered durable attempt identity.
    #[must_use]
    pub fn generate() -> Self {
        Self(Uuid::now_v7())
    }

    /// Parses an attempt identity returned by the control plane.
    ///
    /// # Errors
    ///
    /// Returns [`LifecycleError`] when `value` is not a UUID.
    pub fn parse(value: &str) -> Result<Self, LifecycleError> {
        Uuid::parse_str(value)
            .map(Self)
            .map_err(|_| LifecycleError::InvalidAttemptId(value.to_owned()))
    }
}

impl fmt::Display for AttemptId {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.0.fmt(formatter)
    }
}

/// A caller-provided key that makes a state-changing request idempotent.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(try_from = "String", into = "String")]
pub struct IdempotencyKey(String);

impl IdempotencyKey {
    /// Returns the validated key text.
    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl TryFrom<String> for IdempotencyKey {
    type Error = LifecycleError;

    fn try_from(value: String) -> Result<Self, Self::Error> {
        let valid = !value.is_empty()
            && value.len() <= 128
            && value.bytes().all(|character| {
                character.is_ascii_alphanumeric() || matches!(character, b'.' | b'_' | b'-' | b':')
            });
        if valid {
            Ok(Self(value))
        } else {
            Err(LifecycleError::InvalidIdempotencyKey(value))
        }
    }
}

impl From<IdempotencyKey> for String {
    fn from(value: IdempotencyKey) -> Self {
        value.0
    }
}

/// Maximum changed paths retained for one bounded development candidate.
pub const MAX_CHANGED_PATHS: usize = 256;
/// Maximum aggregate UTF-8 bytes retained for a candidate's changed paths.
pub const MAX_CHANGED_PATH_BYTES: usize = 65_536;
/// Maximum scope violations retained for one bounded candidate.
pub const MAX_SCOPE_VIOLATIONS: usize = MAX_CHANGED_PATHS * 2;
/// Maximum aggregate UTF-8 bytes retained for scope violations.
pub const MAX_SCOPE_VIOLATION_BYTES: usize = 524_288;

/// Returns whether scope-violation evidence is within durable storage and API bounds.
#[must_use]
pub fn scope_violations_are_bounded(violations: &[String]) -> bool {
    violations.len() <= MAX_SCOPE_VIOLATIONS
        && violations
            .iter()
            .try_fold(0_usize, |total, violation| {
                total.checked_add(violation.len())
            })
            .is_some_and(|total| total <= MAX_SCOPE_VIOLATION_BYTES)
}

/// Immutable limits on the files and test code a development task may change.
#[derive(Clone, Debug, Default, Deserialize, Eq, PartialEq, Serialize)]
#[serde(deny_unknown_fields)]
pub struct ChangeConstraints {
    /// Repository-relative files or directory trees the candidate must not change.
    #[serde(default)]
    pub protected_paths: Vec<String>,
    /// Whether changes to dedicated or inline Rust tests are authorized.
    #[serde(default)]
    pub allow_test_edits: bool,
}

impl ChangeConstraints {
    /// Validates bounded, normalized repository-relative protected paths.
    ///
    /// # Errors
    ///
    /// Returns [`ChangeConstraintsError`] for an invalid, duplicate, or oversized
    /// protected-path set.
    pub fn validate(&self) -> Result<(), ChangeConstraintsError> {
        if self.protected_paths.len() > 100 {
            return Err(ChangeConstraintsError::TooManyProtectedPaths(
                self.protected_paths.len(),
            ));
        }
        if self.protected_paths.iter().map(String::len).sum::<usize>() > 16_384 {
            return Err(ChangeConstraintsError::ProtectedPathsTooLarge);
        }
        let mut unique = BTreeSet::new();
        for path in &self.protected_paths {
            if !repository_path_is_valid(path) {
                return Err(ChangeConstraintsError::InvalidProtectedPath(path.clone()));
            }
            if !unique.insert(path) {
                return Err(ChangeConstraintsError::DuplicateProtectedPath(path.clone()));
            }
        }
        Ok(())
    }

    /// Returns the configured path that protects `changed_path`, including a
    /// protected directory's descendants.
    #[must_use]
    pub fn protecting_path<'a>(&'a self, changed_path: &str) -> Option<&'a str> {
        self.protected_paths.iter().find_map(|protected| {
            (changed_path == protected
                || changed_path
                    .strip_prefix(protected.as_str())
                    .is_some_and(|suffix| suffix.starts_with('/')))
            .then_some(protected.as_str())
        })
    }
}

/// Returns whether a path is normalized, bounded, and relative to a repository root.
#[must_use]
pub fn repository_path_is_valid(path: &str) -> bool {
    !path.is_empty()
        && path.len() <= 512
        && !path.starts_with('/')
        && !path.ends_with('/')
        && !path.contains('\\')
        && !path.chars().any(char::is_control)
        && path
            .split('/')
            .all(|component| !component.is_empty() && !matches!(component, "." | ".."))
}

/// A submitted task's change constraints are unsafe or exceed supported bounds.
#[derive(Debug, Error)]
pub enum ChangeConstraintsError {
    /// More protected paths were supplied than the bounded task model permits.
    #[error("at most 100 protected paths are allowed, got {0}")]
    TooManyProtectedPaths(usize),
    /// The combined protected-path input exceeded its bounded storage size.
    #[error("protected paths must total at most 16384 bytes")]
    ProtectedPathsTooLarge,
    /// A protected path was not normalized and repository-relative.
    #[error("protected path must be normalized and repository-relative, got {0:?}")]
    InvalidProtectedPath(String),
    /// The same protected path was submitted more than once.
    #[error("protected path was provided more than once: {0:?}")]
    DuplicateProtectedPath(String),
}

/// A task's requested lifecycle outcome.
#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum TaskDesiredState {
    /// The task may be reconciled into an attempt.
    Active,
    /// No further work may be started for this task.
    Cancelled,
}

/// Persisted lifecycle state of one attempt.
#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum AttemptState {
    /// The attempt is durable but no Kubernetes Job has been created.
    Queued,
    /// A Job has been created and its observation is pending.
    Scheduled,
    /// The Job is observed running.
    Running,
    /// A worker reported successful managed validation.
    Succeeded,
    /// The worker or Kubernetes Job failed.
    Failed,
    /// Cancellation is durable; reconciliation must stop the owned Job.
    CancellationRequested,
    /// Cancellation completed and late reports cannot change this outcome.
    Cancelled,
    /// The owned Job disappeared before a terminal observation.
    Interrupted,
}

impl AttemptState {
    /// Returns whether this state can never be changed by a later worker report.
    #[must_use]
    pub const fn is_terminal(self) -> bool {
        matches!(
            self,
            Self::Succeeded | Self::Failed | Self::Cancelled | Self::Interrupted
        )
    }
}

/// A terminal report emitted by a worker or derived from a Job observation.
#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum AttemptOutcome {
    /// Managed validation completed successfully.
    Succeeded,
    /// Managed validation or its infrastructure failed.
    Failed,
}

impl From<AttemptOutcome> for AttemptState {
    fn from(value: AttemptOutcome) -> Self {
        match value {
            AttemptOutcome::Succeeded => Self::Succeeded,
            AttemptOutcome::Failed => Self::Failed,
        }
    }
}

/// A lifecycle boundary rejected a malformed identifier or invalid transition.
#[derive(Debug, Error)]
pub enum LifecycleError {
    /// A task ID was not a UUID.
    #[error("task ID must be a UUID, got {0:?}")]
    InvalidTaskId(String),
    /// An attempt ID was not a UUID.
    #[error("attempt ID must be a UUID, got {0:?}")]
    InvalidAttemptId(String),
    /// An idempotency key was empty or contained unsupported characters.
    #[error("idempotency key must be 1 to 128 URL-safe identifier characters, got {0:?}")]
    InvalidIdempotencyKey(String),
}

/// An exact, lowercase Git object ID accepted by the first managed worker.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct GitRevision(String);

impl GitRevision {
    /// Parses a full SHA-1 Git revision.
    ///
    /// # Errors
    ///
    /// Returns [`IdentityError`] when `value` is not a 40-character lowercase
    /// hexadecimal revision.
    pub fn parse(value: &str) -> Result<Self, IdentityError> {
        if value.len() == 40
            && value
                .bytes()
                .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
        {
            return Ok(Self(value.to_owned()));
        }

        Err(IdentityError::InvalidGitRevision(value.to_owned()))
    }

    /// Returns the normalized revision text.
    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl fmt::Display for GitRevision {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(&self.0)
    }
}

/// A SHA-256 file digest rendered as lowercase hexadecimal.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Sha256Digest(String);

impl Sha256Digest {
    /// Parses a lowercase SHA-256 hexadecimal digest without a prefix.
    ///
    /// # Errors
    ///
    /// Returns [`IdentityError`] when `value` is not a 64-character lowercase
    /// hexadecimal SHA-256 digest.
    pub fn parse(value: &str) -> Result<Self, IdentityError> {
        if value.len() == 64
            && value
                .bytes()
                .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
        {
            return Ok(Self(value.to_owned()));
        }

        Err(IdentityError::InvalidSha256Digest(value.to_owned()))
    }

    /// Returns the normalized digest text.
    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl fmt::Display for Sha256Digest {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(&self.0)
    }
}

/// A configured immutable source identity was invalid.
#[derive(Debug, Error)]
pub enum IdentityError {
    /// The supplied revision was not a complete lowercase SHA-1 ID.
    #[error("Git revision must be a 40-character lowercase hexadecimal SHA-1, got {0:?}")]
    InvalidGitRevision(String),
    /// The supplied digest was not a lowercase SHA-256 value.
    #[error("SHA-256 digest must be a 64-character lowercase hexadecimal value, got {0:?}")]
    InvalidSha256Digest(String),
}

#[cfg(test)]
mod tests {
    use super::{
        AttemptId, AttemptState, ChangeConstraints, GitRevision, IdempotencyKey,
        MAX_SCOPE_VIOLATIONS, Sha256Digest, TaskId, model_revision, scope_violations_are_bounded,
    };

    #[test]
    fn advances_the_model_for_frozen_change_constraints() {
        assert_eq!(model_revision(), 3);
    }

    #[test]
    fn accepts_complete_lowercase_immutable_identities() -> Result<(), super::IdentityError> {
        let revision = GitRevision::parse("4e67795c0cba21bd82c21bdd6c921417fbe29ff6")?;
        let digest = Sha256Digest::parse(
            "d68ca2ac621c99865bf7b50aabc668f1e9e4b85aa79389c00e13fcda4bb56fc7",
        )?;

        assert_eq!(
            revision.as_str(),
            "4e67795c0cba21bd82c21bdd6c921417fbe29ff6"
        );
        assert_eq!(
            digest.as_str(),
            "d68ca2ac621c99865bf7b50aabc668f1e9e4b85aa79389c00e13fcda4bb56fc7"
        );
        Ok(())
    }

    #[test]
    fn rejects_abbreviated_or_noncanonical_identities() {
        assert!(GitRevision::parse("42f2605").is_err());
        assert!(GitRevision::parse("42F2605D14AA980D14608A8D2F518BC05FCC47B6").is_err());
        assert!(
            Sha256Digest::parse(
                "sha256:d68ca2ac621c99865bf7b50aabc668f1e9e4b85aa79389c00e13fcda4bb56fc7"
            )
            .is_err()
        );
    }

    #[test]
    fn generates_parseable_durable_ids() -> Result<(), super::LifecycleError> {
        let task = TaskId::generate();
        let attempt = AttemptId::generate();

        assert_eq!(TaskId::parse(&task.to_string())?, task);
        assert_eq!(AttemptId::parse(&attempt.to_string())?, attempt);
        Ok(())
    }

    #[test]
    fn accepts_a_bounded_idempotency_key() -> Result<(), super::LifecycleError> {
        let key = IdempotencyKey::try_from("submit:request-123".to_owned())?;

        assert_eq!(key.as_str(), "submit:request-123");
        assert!(IdempotencyKey::try_from("has spaces".to_owned()).is_err());
        Ok(())
    }

    #[test]
    fn validates_and_matches_frozen_protected_paths() {
        let constraints = ChangeConstraints {
            protected_paths: vec!["tests".into(), "src/generated.rs".into()],
            allow_test_edits: false,
        };
        assert!(constraints.validate().is_ok());
        assert_eq!(constraints.protecting_path("tests/api.rs"), Some("tests"));
        assert_eq!(
            constraints.protecting_path("src/generated.rs"),
            Some("src/generated.rs")
        );
        assert_eq!(constraints.protecting_path("src/generated.rs.bak"), None);
        assert_eq!(constraints.protecting_path("src/lib.rs"), None);

        for path in [
            "",
            "/tmp/file",
            "../outside",
            "src/../tests",
            "src\\main.rs",
        ] {
            assert!(
                ChangeConstraints {
                    protected_paths: vec![path.into()],
                    allow_test_edits: false,
                }
                .validate()
                .is_err(),
                "accepted unsafe path {path:?}"
            );
        }
        assert!(
            ChangeConstraints {
                protected_paths: vec!["tests".into(), "tests".into()],
                allow_test_edits: false,
            }
            .validate()
            .is_err()
        );
    }

    #[test]
    fn bounds_retained_scope_violations() {
        assert!(scope_violations_are_bounded(&["violation".into()]));
        assert!(!scope_violations_are_bounded(&vec![
            "violation".into();
            MAX_SCOPE_VIOLATIONS + 1
        ]));
        assert!(!scope_violations_are_bounded(&[
            "x".repeat(super::MAX_SCOPE_VIOLATION_BYTES + 1),
        ]));
    }

    #[test]
    fn identifies_terminal_attempt_states() {
        assert!(!AttemptState::Running.is_terminal());
        assert!(AttemptState::Cancelled.is_terminal());
    }
}
